import{z as B,x as l,o as E,c as p,q as o,j as i,D as e,d as r,s as A,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"绩效归因的深化","description":"","frontmatter":{"title":"绩效归因的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-attribution-deep.md","filePath":"quant/pf-attribution-deep.md","lastUpdated":1791063341000}'),d={name:"quant/pf-attribution-deep.md"};function u(h,a,f,m,c,D){const n=l("Mermaid");return E(),p("div",null,[a[2]||(a[2]=o('<h1 id="绩效归因的深化" tabindex="-1">绩效归因的深化 <a class="header-anchor" href="#绩效归因的深化" aria-label="Permalink to &quot;绩效归因的深化&quot;">​</a></h1><div class="epigraph"><p>归因不是成绩单，是账本审计：它的首要美德不是好看，而是闭合——每一分超额都有去处，每一处残差都有名字。</p><footer>—— 据 Brinson and Fachler, Journal of Portfolio Management, 1985；Carino, Journal of Portfolio Management, 1999；Menchero, Journal of Performance Measurement, 2000 整理</footer></div><p><a href="/quant/pf-stress-testing">上一课</a>把情景库接进行动闭环；组合跑起来了，报告季的问题随之而来：超额收益从哪来。组件的课已有：<a href="/quant/brinson">Brinson 归因</a>的配置、选择与交互，<a href="/quant/factor-attribution">因子归因</a>的回归口径，<a href="/quant/trade-level-attribution">交易层级归因</a>的执行拆解。本课深化三件主干没展开的事：多期闭合、口径一致性、与事前风险的对接。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单期的 Brinson 分解是算术，多期就是问题：各期「配置+选择+交互」简单加总，与累计超额对不上——复利是非线性的，几何效应真实存在。不闭合的归因没法对账：凭空出现或消失的几十个基点，恰好是管理层最想追问的地方。第二类病是口径打架：业绩用时间加权（<a href="/quant/twr-vs-mwr">时间加权对资金加权</a>），归因用的基准时点与现金流假设却与业绩系统不同；Brinson 的分区与因子归因的回归窗口不一致，两份报告给出两个「主动管理来源」，投委会不知道信谁。第三类病是残差黑洞：回归归因的残差项没有预算，常年超线，说明模型漏了载荷——残差被当成「未解释的正常现象」，而不是警报。</p><p><span class="marginnote">基点（bp）就是一个百分点的百分之一，即 0.01%。数字实例：规模 10 亿元的组合，50 个 bp 的残差就是 500 万元——归因账里凭空消失的几十个基点，换算成钱后足以值得开一次正式的审计会。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把归因当账本工程来做：多期闭合用连接算法把几何效应分配掉，层次上让归因树逐层复刻决策树，对接上把事后因子桶与事前风险模型的因子桶逐一钉齐；三件事之上再立一条残差的绝对预算，超线即触发载荷复核。所有口径事先写进约定表——分区、窗口、现金流假设一旦漂移，闭合与对接同时作废。</p><h3 id="闭合、层次、对接" tabindex="-1">闭合、层次、对接 <a class="header-anchor" href="#闭合、层次、对接" aria-label="Permalink to &quot;闭合、层次、对接&quot;">​</a></h3><p>多期闭合：Carino（1999）与 Menchero（2000）一族的连接算法，用平滑系数把单期贡献调整为可加——几何效应从「消失」变成「被分配」；选哪一种算法是会计惯例不是真理，但必须事先钉进约定表（因子研究深化课程的报告规范口径在此通用）。层次一致：归因树必须复刻决策树——战略配置、类别内配置、证券选择、交易执行（接<a href="/quant/trade-level-attribution">交易层级归因</a>与<a href="/quant/slippage-attribution">滑点归因</a>），每一层的基准是上一层的输出；层级错位的归因，算的是投资者根本没做过的决策。风险对接：把事后归因与事前风险模型对齐（<a href="/quant/fundamental-risk-model">Barra / 基本面风险模型</a>）——主动收益的每个因子桶对应主动风险的因子桶，报告从「赚了多少钱」升级为「赚了哪个风险的钱、付了多少风险」；主动份额（<a href="/quant/active-share">主动份额</a>）与跟踪误差（<a href="/quant/benchmark-tracking-error">基准与跟踪误差</a>）是对接时的两把标尺。</p><p><span class="marginnote">「交互项」就是配置与选择叠加后多出来的一小块：数字实例——超配了当期上涨 10% 的行业（配置贡献为正），又恰好在这个行业里选中了再跑赢 5% 的股票，两笔贡献的耦合部分若没人认领，多期加总时就会变成对不上的残差。Brinson 把它单列成第三项，就是为了让账本闭合。</span></p>',11)),(E(),i(s,null,{default:e(()=>[A(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TWR%5B%22%E6%97%B6%E9%97%B4%E5%8A%A0%E6%9D%83%E4%B8%9A%E7%BB%A9%E4%B8%8E%E5%9F%BA%E5%87%86%22%5D%20--%3E%20TREE%5B%22%E5%B1%82%E7%BA%A7%E5%88%86%E8%A7%A3%EF%BC%9A%E9%85%8D%E7%BD%AE%2F%E9%80%89%E6%8B%A9%2F%E4%BA%A4%E6%98%93%22%5D%0A%20%20TREE%20--%3E%20LINK%5B%22%E5%A4%9A%E6%9C%9F%E8%BF%9E%E6%8E%A5%EF%BC%9ACarino%20%E6%88%96%20Menchero%22%5D%0A%20%20LINK%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E6%A3%80%E9%AA%8C%EF%BC%9A%E7%BB%9D%E5%AF%B9%E9%A2%84%E7%AE%97%E4%B8%8E%E8%B6%85%E7%BA%BF%E8%A7%A6%E5%8F%91%22%5D%0A%20%20RES%20--%3E%20RISK%5B%22%E4%B8%8E%E4%BA%8B%E5%89%8D%E9%A3%8E%E9%99%A9%E6%A8%A1%E5%9E%8B%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20RISK%20--%3E%20REPORT%5B%22%E5%8F%AF%E5%AF%B9%E8%B4%A6%E7%9A%84%E5%BD%92%E5%9B%A0%E6%8A%A5%E5%91%8A%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"闭合为什么是第一美德：不闭合的分解允许贡献凭空出入，而多期几何效应是真实存在的钱——把它塞进残差或干脆丢掉，是账本意义上的失真。连接算法的差别只是把几何效应分配给谁：Carino 分给全体、Menchero 按贡献比例，这是惯例之争；惯例本身必须稳定，否则两期报告之间的「改善」可能只是换了算法。口径一致性为什么贵在事先：Brinson 需要分区、因子归因需要载荷与窗口，两套约定各自合理，拼起来就打架——治理的办法是把分区、窗口、现金流假设写进一份约定表，所有报告从同一张表生成。残差预算为什么能当模型体检：给 |残差| 设一条线（例如年化超额的一成），逐月监控，超线触发载荷复核——归因系统由此从展示工具变成发现工具，因子模型的漂移最先在残差上露头。",-1)),(E(),i(s,null,{default:e(()=>[A(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E7%AC%AC%E4%B8%80%E6%9C%9F%E8%B6%85%E9%A2%9D%20%2B10%25%22%5D%20--%3E%20G%5B%22%E5%87%A0%E4%BD%95%E5%A4%8D%E5%88%A9%EF%BC%9A1.10%20%C3%97%201.10%22%5D%0A%20%20P2%5B%22%E7%AC%AC%E4%BA%8C%E6%9C%9F%E8%B6%85%E9%A2%9D%20%2B10%25%22%5D%20--%3E%20G%0A%20%20G%20--%3E%20C%5B%22%E7%B4%AF%E8%AE%A1%E8%B6%85%E9%A2%9D%E5%85%B6%E5%AE%9E%E6%98%AF%2021%25%22%5D%0A%20%20C%20--%3E%20S%5B%22%E5%90%84%E6%9C%9F%E7%AE%80%E5%8D%95%E5%8A%A0%E6%80%BB%E5%8F%AA%E7%BB%99%2020%25%22%5D%0A%20%20S%20--%3E%20GAP%5B%22%E5%B7%AE%E7%9A%84%201%20%E4%B8%AA%E7%99%BE%E5%88%86%E7%82%B9%E5%B0%B1%E6%98%AF%E5%87%A0%E4%BD%95%E6%95%88%E5%BA%94%22%5D%0A%20%20GAP%20--%3E%20L%5B%22%E8%BF%9E%E6%8E%A5%E7%AE%97%E6%B3%95%E6%8A%8A%E5%AE%83%E5%88%86%E9%85%8D%E5%9B%9E%E5%90%84%E6%9C%9F%E8%B4%A1%E7%8C%AE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">为什么残差预算重要：残差是模型漏掉的载荷的藏身处。若某月残差突然放大，往往不是运气，而是组合新暴露了模型里没有的因子（比如悄悄押上了长久期利率）。设线、监控、超线即复核，能在「模型漂移」变成大亏损之前把它抓出来。</span></p><p><span class="marginnote">量级感受：年化 2% 的超额若逐月简单加总不闭合，年度残差可达几十个基点——足以淹没一位真实管理人的全部配置贡献；闭合与否，直接决定归因是证据还是修辞。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推 Brinson 代数（<a href="/quant/brinson">Brinson 归因</a>），不重写因子回归的设定（<a href="/quant/factor-attribution">因子归因</a>）；费前费后与业绩展示的行业规范不在本课。机器学习的归因工具（<a href="/quant/shap-factor-attribution">SHAP 因子归因</a>）是另一族口径，接口已通：它的分解同样要过多期闭合与残差预算两道检验。固定收益归因（曲线、利差、carry）的结构不同，此处只点名；归因发现的问题流向何处——限额、模型复核、还是下一轮构建——是风险治理课程的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多期闭合是归因的第一美德：连接算法把几何效应分配掉，算法是惯例、惯例要钉死。</li><li>归因树复刻决策树：每层基准是上层输出，层级错位等于在算别人没做过的决策。</li><li>事后归因与事前风险对账：从「赚了多少」升级到「赚了哪个风险的钱」。</li><li>残差要有绝对预算与超线触发：归因系统由此变成模型体检工具。</li><li>出处：Brinson &amp; Fachler, <em>JPM</em>, 1985；Brinson, Hood &amp; Beebower, <em>FAJ</em>, 1986；Carino, <em>JPM</em>, 1999；Menchero, <em>Journal of Performance Measurement</em>, 2000。</li></ul>',6))])}const C=B(d,[["render",u]]);export{q as __pageData,C as default};
